-- labdb benchmark data (generated by scripts/benchmarks/labdb_benchmark.py). Add-only: it fails if the
-- tables exist; to reload, drop employees, sales and transactions yourself first.
CREATE TABLE employees (id INT PRIMARY KEY, name VARCHAR(80) NOT NULL, department VARCHAR(40) NOT NULL, salary INT NOT NULL, hire_date DATE NOT NULL);
CREATE TABLE sales (id INT PRIMARY KEY, sale_date DATE NOT NULL, region VARCHAR(20) NOT NULL, product VARCHAR(40) NOT NULL, amount DECIMAL(10,2) NOT NULL);
CREATE TABLE transactions (id INT PRIMARY KEY, customer VARCHAR(80) NOT NULL, amount DECIMAL(10,2) NOT NULL, created_at DATE NOT NULL);
